'use strict';

// The remote port's web page: pairs from the fragment of the URL the
// host's QR code carries, lists the sessions with the waiting ones
// first, shows a session's last response or screen, and sends a reply.
// It speaks what the headset speaks (docs/remote-client.md §4) and
// keeps nothing but the host's public identity; the credential is a
// cookie this script cannot read. Plain DOM, `textContent` only, no
// dependency. The pure parts at the top are what `app.test.js` covers.

// Every path the page reads, in one place so a test can check that the
// host answers each. `{id}` is a project's id under `/projects/` and a
// session's elsewhere.
const API = {
  info: '/api/v1/info',
  pair: '/api/v1/pair',
  me: '/api/v1/me',
  projects: '/api/v1/projects',
  sessions: '/api/v1/projects/{id}/sessions',
  waiting: '/api/v1/waiting',
  lastResponse: '/api/v1/sessions/{id}/last-response',
  screen: '/api/v1/sessions/{id}/screen',
  send: '/api/v1/sessions/{id}/send',
  events: '/api/v1/events',
};

const STORAGE_KEY = 'switchboard-host';
const POLL_MS = 3000;
const POLL_SLOW_MS = 20000;
const SOCKET_RETRY_MS = 5000;
const SOCKET_RETRY_MAX_MS = 60000;

// --- pure parts

// The pairing values in a URL fragment: `#code=…&key=…&id=…`, or null
// when any of the three is missing.
function parseFragment(hash) {
  const text = (hash || '').replace(/^#/, '');
  if (!text) return null;
  const values = {};
  for (const pair of text.split('&')) {
    const at = pair.indexOf('=');
    if (at <= 0) continue;
    const name = decodeURIComponent(pair.slice(0, at));
    const value = decodeURIComponent(pair.slice(at + 1));
    values[name] = value;
  }
  if (!values.code || !values.key || !values.id) return null;
  return { code: values.code, key: values.key, id: values.id };
}

// What the host lists this browser as: the browser "on" the device,
// from the user agent, with a Macintosh that reports touch counted as
// an iPad (Safari on iPadOS says Macintosh).
function deviceName(userAgent, touchPoints) {
  const ua = userAgent || '';
  let browser = 'Safari';
  if (/Edg\//.test(ua)) browser = 'Edge';
  else if (/Chrome\//.test(ua)) browser = 'Chrome';
  else if (/Firefox\//.test(ua)) browser = 'Firefox';
  let device = '';
  if (/iPhone/.test(ua)) device = 'iPhone';
  else if (/iPad/.test(ua)) device = 'iPad';
  else if (/Macintosh/.test(ua)) device = touchPoints > 1 ? 'iPad' : 'Mac';
  else if (/Android/.test(ua)) device = 'Android';
  else if (/Windows/.test(ua)) device = 'Windows';
  else if (/Linux/.test(ua)) device = 'Linux';
  if (!browser && !device) return 'Browser';
  return device ? `${browser} on ${device}` : browser;
}

// Why a request was refused 401, told from `/info`, which the page can
// read unpaired: `stored` is what the page kept of the host it paired
// with, `info` the body `/info` answered now or null when it did not.
// The host cannot say "revoked" (a revoked token and an unknown one are
// the same refusal), so the page infers it from the identity standing.
function inferUnauthorized(stored, info) {
  if (!info) return 'unreachable';
  if (!stored) return 'not_paired';
  if (stored.server_id === info.server_id && stored.spki_sha256 === info.spki_sha256) {
    return 'removed';
  }
  return 'identity_changed';
}

const UNAUTHORIZED_TEXT = {
  unreachable: ['Can\'t reach the host', 'The Mac did not answer. Check that it is on and on this network.'],
  not_paired: ['Not paired', 'Open Remote devices on the Mac, allow pairing, and scan its code with this phone.'],
  removed: ['Removed on the host', 'This device was removed on the Mac. Open its pairing window and scan the code again.'],
  identity_changed: ['Identity changed', 'The host at this address is not the one this browser paired with, or its key was remade. Pair again from its window.'],
};

// Whether a reply at (epoch, revision) is at or past what the page
// holds (§4.4): a reply from an earlier revision is dropped, and a new
// epoch (the host restarted) always applies.
function accepts(held, reply) {
  if (!held) return true;
  if (held.epoch !== reply.epoch) return true;
  return reply.revision >= held.revision;
}

// The list as the page shows it: projects with a waiting session
// first, waiting sessions first within a project, then by last
// activity, newest first, name as the tie-break. Pure over the two
// replies so a test can call it.
function orderList(projects, sessionsByProject) {
  const groups = projects.map((project) => {
    const sessions = (sessionsByProject[project.id] || []).slice();
    sessions.sort((a, b) => {
      if (Boolean(a.waiting) !== Boolean(b.waiting)) return a.waiting ? -1 : 1;
      const ta = a.last_activity_ms || 0;
      const tb = b.last_activity_ms || 0;
      if (ta !== tb) return tb - ta;
      return String(a.name).localeCompare(String(b.name));
    });
    return { project, sessions, waiting: sessions.some((s) => s.waiting) };
  });
  groups.sort((a, b) => {
    if (a.waiting !== b.waiting) return a.waiting ? -1 : 1;
    return String(a.project.name).localeCompare(String(b.project.name));
  });
  return groups;
}

// "3 m ago", "2 h ago"; '' with no time.
function sinceText(ms, now) {
  if (!ms) return '';
  const s = Math.max(0, Math.floor((now - ms) / 1000));
  if (s < 60) return 'just now';
  const m = Math.floor(s / 60);
  if (m < 60) return `${m} m ago`;
  const h = Math.floor(m / 60);
  if (h < 48) return `${h} h ago`;
  return `${Math.floor(h / 24)} d ago`;
}

// The reply box's operation id: random hex, kept across a retry so a
// send whose reply was lost is answered from the host's log rather
// than typed twice. `getRandomValues` exists outside a secure context.
function newOp(randomValues) {
  const bytes = new Uint8Array(16);
  randomValues(bytes);
  return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    API,
    parseFragment,
    deviceName,
    inferUnauthorized,
    accepts,
    orderList,
    sinceText,
    newOp,
  };
}

// --- the page

if (typeof document !== 'undefined') {
  const $ = (id) => document.getElementById(id);

  const state = {
    me: null,
    stored: null,
    held: null,
    groups: [],
    open: null,
    openView: null,
    pendingOp: null,
    socket: null,
    socketRetryMs: SOCKET_RETRY_MS,
    pollTimer: null,
    pollMs: POLL_MS,
  };

  function show(section) {
    for (const id of ['boot', 'notice', 'list', 'session']) {
      $(id).hidden = id !== section;
    }
  }

  function notice(title, text) {
    $('notice-title').textContent = title;
    $('notice-text').textContent = text;
    show('notice');
  }

  function loadStored() {
    try {
      const text = localStorage.getItem(STORAGE_KEY);
      return text ? JSON.parse(text) : null;
    } catch (e) {
      return null;
    }
  }

  function saveStored(value) {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(value));
    } catch (e) {
      // Private browsing may refuse; the page then forgets on reload.
    }
    state.stored = value;
  }

  // One request to the host; the cookie rides along as the browser's
  // own credential. The reply is the parsed envelope with its status.
  async function api(method, path, body) {
    const init = { method, credentials: 'same-origin', headers: {} };
    if (body !== undefined) {
      init.headers['Content-Type'] = 'application/json';
      init.body = JSON.stringify(body);
    }
    let response;
    try {
      response = await fetch(path, init);
    } catch (e) {
      return { status: 0, json: null };
    }
    let json = null;
    try {
      json = await response.json();
    } catch (e) {
      json = null;
    }
    return { status: response.status, json };
  }

  function errorCode(reply) {
    return reply.json && reply.json.error ? reply.json.error.code : '';
  }

  async function unauthorized() {
    stopRefresh();
    const info = await api('GET', API.info);
    const kind = inferUnauthorized(state.stored, info.status === 200 ? info.json.body : null);
    const [title, text] = UNAUTHORIZED_TEXT[kind];
    notice(title, text);
  }

  // The reply, or null after a refusal was shown.
  async function read(path) {
    const reply = await api('GET', path);
    if (reply.status === 401) {
      await unauthorized();
      return null;
    }
    if (reply.status === 0) {
      notice(UNAUTHORIZED_TEXT.unreachable[0], UNAUTHORIZED_TEXT.unreachable[1]);
      return null;
    }
    return reply;
  }

  async function boot() {
    state.stored = loadStored();
    const fragment = parseFragment(location.hash);
    if (fragment) {
      // The code leaves the address bar before anything else happens.
      history.replaceState(null, '', location.pathname);
      await pair(fragment);
      return;
    }
    const me = await api('GET', API.me);
    if (me.status === 200) {
      becamePaired(me.json.body);
      return;
    }
    if (me.status === 401) {
      await unauthorized();
      return;
    }
    notice(UNAUTHORIZED_TEXT.unreachable[0], UNAUTHORIZED_TEXT.unreachable[1]);
  }

  const PAIR_TEXT = {
    pairing_closed: 'The pairing window on the Mac is closed. Allow pairing again and scan the new code.',
    wrong_code: 'The code does not match. Scan the code the Mac shows now.',
    wrong_key: 'This is not the host the code was scanned from.',
    rate_limited: 'Too many pairing attempts. Wait a minute and scan again.',
  };

  async function pair(fragment) {
    $('boot-text').textContent = 'Pairing…';
    const info = await api('GET', API.info);
    if (info.status !== 200) {
      notice(UNAUTHORIZED_TEXT.unreachable[0], UNAUTHORIZED_TEXT.unreachable[1]);
      return;
    }
    const host = info.json.body;
    if (host.spki_sha256 !== fragment.key || host.server_id !== fragment.id) {
      notice('Different host', 'This address is a different Switchboard than the code was for. Nothing was sent.');
      return;
    }
    const reply = await api('POST', API.pair, {
      code: fragment.code,
      spki_sha256: fragment.key,
      device_name: deviceName(navigator.userAgent, navigator.maxTouchPoints || 0),
      transport: 'cookie',
    });
    if (reply.status !== 200) {
      const code = errorCode(reply);
      notice('Not paired', PAIR_TEXT[code] || `The host refused the pairing (${code || reply.status}).`);
      return;
    }
    saveStored({
      server_id: host.server_id,
      spki_sha256: host.spki_sha256,
      server_name: host.server_name,
    });
    const me = await api('GET', API.me);
    if (me.status !== 200) {
      await unauthorized();
      return;
    }
    becamePaired(me.json.body);
  }

  function becamePaired(me) {
    state.me = me;
    $('host-name').textContent = me.server_name;
    $('scope').textContent = me.scope;
    $('header').hidden = false;
    show('list');
    refreshAll();
    startRefresh();
  }

  async function refreshMe() {
    const reply = await read(API.me);
    if (reply && reply.status === 200) {
      state.me = reply.json.body;
      $('scope').textContent = state.me.scope;
    }
  }

  // --- the list

  async function refreshList() {
    const projects = await read(API.projects);
    if (!projects || projects.status !== 200) return;
    const list = projects.json.body.projects || [];
    const sessionsByProject = {};
    for (const project of list) {
      const reply = await read(API.sessions.replace('{id}', project.id));
      if (!reply) return;
      sessionsByProject[project.id] = reply.status === 200 ? reply.json.body.sessions || [] : [];
    }
    state.groups = orderList(list, sessionsByProject);
    renderList();
  }

  function renderList() {
    const root = $('projects');
    root.textContent = '';
    const now = Date.now();
    let count = 0;
    for (const group of state.groups) {
      if (group.sessions.length === 0) continue;
      const title = document.createElement('h2');
      title.textContent = group.project.name;
      root.appendChild(title);
      for (const session of group.sessions) {
        count += 1;
        const row = document.createElement('button');
        row.type = 'button';
        row.className = session.waiting ? 'session-row is-waiting' : 'session-row';
        if (session.waiting) {
          const waiting = document.createElement('span');
          waiting.className = 'line waiting';
          waiting.textContent = session.waiting_reason
            ? `Waiting on you: ${session.waiting_reason}`
            : 'Waiting on you';
          row.appendChild(waiting);
        }
        const name = document.createElement('span');
        name.className = 'line name';
        name.textContent = session.name;
        row.appendChild(name);
        const meta = document.createElement('span');
        meta.className = 'line meta';
        const since = sinceText(session.last_activity_ms, now);
        meta.textContent = [session.kind, session.card, since].filter(Boolean).join(' · ');
        row.appendChild(meta);
        row.addEventListener('click', () => openSession(session));
        root.appendChild(row);
      }
    }
    $('list-empty').hidden = count !== 0;
  }

  // --- a session

  function openSession(session) {
    state.open = session;
    state.pendingOp = null;
    $('session-name').textContent = session.name;
    $('session-text').textContent = '';
    $('session-truncated').hidden = true;
    $('send-status').textContent = '';
    $('reply-text').value = '';
    show('session');
    renderSessionMeta();
    refreshSession();
  }

  function renderSessionMeta() {
    const session = state.open;
    if (!session) return;
    $('session-meta').textContent = [session.kind, session.card].filter(Boolean).join(' · ');
    const waiting = $('session-waiting');
    waiting.hidden = !session.waiting;
    waiting.textContent = session.waiting_reason
      ? `Waiting on you: ${session.waiting_reason}`
      : 'Waiting on you';
    const canSend = state.me && state.me.scope === 'control' && !session.prompt_refusal;
    $('reply').hidden = !canSend;
    const refusal = $('refusal');
    refusal.hidden = !(state.me && state.me.scope === 'control' && session.prompt_refusal);
    refusal.textContent = session.prompt_refusal ? `No reply: ${session.prompt_refusal}` : '';
  }

  async function refreshSession() {
    const session = state.open;
    if (!session) return;
    const path = session.kind === 'claude' ? API.lastResponse : API.screen;
    const reply = await read(path.replace('{id}', session.id));
    if (!reply || state.open !== session) return;
    if (reply.status !== 200) {
      const message = reply.json && reply.json.error ? reply.json.error.message : `HTTP ${reply.status}`;
      $('session-text').textContent = message;
      return;
    }
    if (state.openView && !accepts(state.openView, reply.json)) return;
    state.openView = { epoch: reply.json.epoch, revision: reply.json.revision };
    $('session-text').textContent = reply.json.body.text || '';
    $('session-truncated').hidden = !reply.json.body.truncated;
  }

  // The session as the list now says it is, so the card word and the
  // refusal follow a refetch.
  function syncOpenFromList() {
    if (!state.open) return;
    for (const group of state.groups) {
      const found = group.sessions.find((s) => s.id === state.open.id);
      if (found) {
        state.open = found;
        renderSessionMeta();
        return;
      }
    }
  }

  async function send(event) {
    event.preventDefault();
    const session = state.open;
    const text = $('reply-text').value;
    if (!session || !text.trim()) return;
    if (!state.pendingOp) state.pendingOp = newOp((b) => crypto.getRandomValues(b));
    const op = state.pendingOp;
    $('send').disabled = true;
    $('send-status').textContent = 'Sending…';
    const reply = await api('POST', API.send.replace('{id}', session.id), { op, text });
    $('send').disabled = false;
    if (reply.status === 401) {
      await unauthorized();
      return;
    }
    if (reply.status === 0) {
      $('send-status').textContent = 'No answer; Send again repeats the same operation.';
      return;
    }
    const code = errorCode(reply);
    if (reply.status === 403 && code === 'scope') {
      $('send-status').textContent = 'This device reads only now.';
      await refreshMe();
      renderSessionMeta();
      return;
    }
    if (reply.status !== 200) {
      const message = reply.json && reply.json.error ? reply.json.error.message : `HTTP ${reply.status}`;
      $('send-status').textContent = message;
      state.pendingOp = null;
      return;
    }
    state.pendingOp = null;
    $('reply-text').value = '';
    $('send-status').textContent = 'Sent';
  }

  // --- refresh: polling as the base, the socket as the enhancement

  async function refreshAll() {
    await refreshList();
    syncOpenFromList();
    await refreshSession();
  }

  async function poll() {
    if (document.hidden) return;
    const reply = await read(API.waiting);
    if (!reply || reply.status !== 200) return;
    const seen = { epoch: reply.json.epoch, revision: reply.json.revision };
    if (state.held && state.held.epoch === seen.epoch && state.held.revision === seen.revision) {
      return;
