425	  async function refreshSession() {
426	    const session = state.open;
427	    if (!session) return;
428	    const path = session.kind === 'claude' ? API.lastResponse : API.screen;
429	    const reply = await read(path.replace('{id}', session.id));
430	    if (!reply || state.open !== session) return;
431	    if (reply.status !== 200) {
432	      const message = reply.json && reply.json.error ? reply.json.error.message : `HTTP ${reply.status}`;
433	      $('session-text').textContent = message;
434	      return;
435	    }
436	    if (state.openView && !accepts(state.openView, reply.json)) return;
437	    state.openView = { epoch: reply.json.epoch, revision: reply.json.revision };
438	    $('session-text').textContent = reply.json.body.text || '';
439	    $('session-truncated').hidden = !reply.json.body.truncated;
440	  }
